exercises.solution:
function formatarReais(centavos) {
  return `R$ ${(centavos / 100).toFixed(2).replace('.', ',')}`;
}

const cafes = [650, 700, 650, 800, 650, 700];

let total = 0;
for (let i = 0; i < cafes.length; i++) {
  if ((i + 1) % 3 === 0) {
    console.log(`Café ${i + 1}: grátis`);
  } else {
    console.log(`Café ${i + 1}: ${formatarReais(cafes[i])}`);
    total = total + cafes[i];
  }
}
console.log(`Total: ${formatarReais(total)}`);
